// CIP-30 discovery follows the registry/alias approach used by CoindropV2.
// Wallet connection alone never grants access to a Strike account.
import {hex,ORIGINS} from './protocol.mjs';
export const WALLET_REGISTRY=[['nami','Nami',['nami']],['eternl','Eternl',['eternl','ccvault']],['lace','Lace',['lace']],['flint','Flint',['flint']],['yoroi','Yoroi',['yoroi']],['typhon','Typhon',['typhoncip30','typhon']],['nufi','NuFi',['nufi']],['gero','Gero',['gerowallet','gero']],['vespr','VESPR',['vespr']],['begin','Begin',['begin']],['tokeo','Tokeo',['tokeo']]];
export function discoverCardano(root={}){const used=new Set(),rows=WALLET_REGISTRY.map(([id,name,aliases])=>{const key=aliases.find(k=>typeof root[k]?.enable==='function');if(key)used.add(key);return {id,name,key,installed:!!key}});for(const key of Object.keys(root))if(!used.has(key)&&typeof root[key]?.enable==='function'&&!WALLET_REGISTRY.some(r=>r[2].includes(key)))rows.push({id:key,name:key,key,installed:true});return rows;}
function polymod(values){let c=1;const g=[0x3b6a57b2,0x26508e6d,0x1ea119fa,0x3d4233dd,0x2a1462b3];for(const v of values){const b=c>>>25;c=((c&0x1ffffff)<<5)^v;for(let i=0;i<5;i++)if((b>>>i)&1)c^=g[i]}return c>>>0}
export function cardanoAddress(raw,network){if(typeof raw!=='string'||!/^([0-9a-fA-F]{2})+$/.test(raw))throw Error('Invalid CIP-30 address');const bytes=Uint8Array.from(raw.match(/../g),x=>parseInt(x,16)),kind=bytes[0]>>>4,n=bytes[0]&15;if(![0,1,2,3,6,7].includes(kind)||bytes.length!==([6,7].includes(kind)?29:57))throw Error('Unsupported Cardano payment address');if(n!==network||![0,1].includes(n))throw Error('Wallet address network mismatch');const hrp=n===1?'addr':'addr_test',data=[];let acc=0,bits=0;for(const b of bytes){acc=((acc<<8)|b)&0xffffff;bits+=8;while(bits>=5){bits-=5;data.push((acc>>>bits)&31)}}if(bits)data.push((acc<<(5-bits))&31);const expanded=[...hrp].map(c=>c.charCodeAt(0)>>>5).concat([0],[...hrp].map(c=>c.charCodeAt(0)&31)),m=polymod([...expanded,...data,0,0,0,0,0,0])^1;const checksum=Array.from({length:6},(_,i)=>(m>>>(5*(5-i)))&31);return hrp+'1'+[...data,...checksum].map(v=>'qpzry9x8gf2tvdw0s3jn54khce6mua7l'[v]).join('')}
export async function connectCardano(root,id,network){const row=discoverCardano(root).find(r=>r.id===id&&r.installed);if(!row)throw Error('Selected wallet is not installed');const api=await root[row.key].enable();const networkId=await api.getNetworkId();if(networkId!==(network==='mainnet'?1:0))throw Error('Switch your wallet network to match Guardian, then reconnect');const raw=await api.getChangeAddress();return {api,raw,address:cardanoAddress(raw,networkId),network,name:row.name};}
export async function requestBuilder(session,code,{fetcher=fetch,subtle=crypto.subtle,clock=()=>Date.now()}={}){if(typeof code!=='string'||!code.trim()||code.length>128)throw Error('A registered active Strike Builder Code is required');if(typeof session.api.signData!=='function')throw Error('This wallet does not support CIP-30 signData');const pair=await subtle.generateKey('Ed25519',false,['sign','verify']),publicKey=hex(await subtle.exportKey('raw',pair.publicKey));const response=await fetcher(ORIGINS[session.network]+'/auth/builder/request-signature',{method:'POST',credentials:'omit',headers:{'Content-Type':'application/json'},body:JSON.stringify({address:session.address,chain:'cardano',code:code.trim(),fee_share_bps:0,public_key:publicKey}),signal:AbortSignal.timeout(10000)});const data=await response.json();if(!response.ok)throw Error(data.error||'Strike challenge request failed: '+response.status);if(typeof data.nonce!=='string'||typeof data.message_to_sign!=='string'||!data.message_to_sign||data.message_to_sign.length>20000)throw Error('Invalid official authorization challenge');return {session,code:code.trim(),publicKey,message:data.message_to_sign,nonce:data.nonce,createdAt:clock(),wallet:{publicKey,sign:async bytes=>new Uint8Array(await subtle.sign('Ed25519',pair.privateKey,bytes))}};}
export async function finishBuilder(pending,{fetcher=fetch,clock=()=>Date.now()}={}){if(clock()-pending.createdAt>290000)throw Error('Authorization challenge expired; request a new one');if(await pending.session.api.getChangeAddress()!==pending.session.raw||await pending.session.api.getNetworkId()!==(pending.session.network==='mainnet'?1:0))throw Error('Wallet account or network changed; reconnect');const signed=await pending.session.api.signData(pending.session.raw,hex(new TextEncoder().encode(pending.message)));if(!signed||!/^([a-f0-9]{2})+$/i.test(signed.signature)||!/^([a-f0-9]{2})+$/i.test(signed.key))throw Error('Invalid CIP-30 data signature');const r=await fetcher(ORIGINS[pending.session.network]+'/auth/builder/verify-signature',{method:'POST',credentials:'omit',headers:{'Content-Type':'application/json'},body:JSON.stringify({nonce:pending.nonce,wallet_signature:signed.signature+':'+signed.key}),signal:AbortSignal.timeout(10000)}),data=await r.json();if(!r.ok)throw Error(data.error||'Strike signature verification failed: '+r.status);if(data.api_wallet_public_key?.toLowerCase()!==pending.publicKey||data.builder_code!==pending.code||data.fee_share_bps!==0||!data.account_id||!Number.isFinite(Date.parse(data.api_wallet_expired_at))||Date.parse(data.api_wallet_expired_at)<=clock())throw Error('Strike authorization response does not match the approved session');return {wallet:pending.wallet,accountId:data.account_id};}
